-- Dedicated public introduction pages, editable only through administrator actions.
ALTER TABLE handa_content DROP CONSTRAINT handa_content_kind_check;
ALTER TABLE handa_content ADD CONSTRAINT handa_content_kind_check CHECK(kind IN ('home','wiki','member','story','testimonial','page'));
ALTER TABLE handa_content ADD CONSTRAINT handa_fixed_pages CHECK(kind <> 'page' OR (content_key IN ('about','guide','join') AND status='published'));
INSERT INTO handa_content(kind,content_key,payload,status,is_example,publication_consent,sort_order) VALUES
('page','about','{"isExample": false, "secondaryHeading": "", "secondaryBody": "", "ctaLabel": "HANDA 참여 신청하기", "ctaUrl": "https://forms.gle/SXXxb8321efoPFta8", "slug": "about", "title": "HANDA란?", "heading": "HANDA를 소개합니다.", "body": "HANDA는 베를린에서 각자의 사업을 실제로 실행하고 성장시키는\n창업자들의 커뮤니티입니다.\n함께하면 더 멀리 갈 수 있다는 믿음으로,\n2025년 12월 작은 모임에서 시작했습니다.\nHANDA에서는 매달 목표를 세우고, 직접 실행하고,\n같은 공간에서 서로의 과정을 솔직하게 리뷰합니다.\n단순히 경험을 나누는 데 그치지 않고,\n다음 행동으로 이어지는 것이 HANDA가 추구하는 방식입니다.\nHANDA에서는 이렇게 함께 합니다.\n[실행엔진]\n매달 목표와 실행 결과, 진행 과정에서 막힌 점을 기록하고 공유합니다.\n각자의 계획이 실제 행동으로 이어지도록 돕습니다.\n[정기모임]\n매달 둘째 주 일요일, 멤버들이 한자리에 모여\n각자의 실행을 공유하고 서로의 고민과 병목을 함께 풀어갑니다.\n[비즈니스 위키]\n실제 창업자들이 사업을 운영하며 얻은 경험과 실전 노하우를 공유합니다.\n법인 설립 절차와 비용부터 팝업스토어 기획 및 성사 과정까지,\n검색만으로는 알기 어려운 생생한 정보를 서로 나눕니다.\n이런 분과 잘 맞습니다\n· 베를린에서 사업을 운영하고 있거나 곧 런칭을 준비하는 분\n· 혼자 고민하기보다 다른 창업자들과 함께 움직이고 싶은 분\n· 좋은 아이디어를 실제 행동과 결과로 연결하고 싶은 분\n함께 만든 변화\nHANDA에서는 아이디어가 3개월 만에 실제 서비스로 발전하고,\n첫 오프라인 이벤트가 열리고,\n새로운 사업 기회와 협업이 연결되는 경험들이 만들어지고 있습니다.\n작은 실행이 모여 각자의 사업을 한 걸음씩 앞으로 나아가게 합니다.\n혼자 고민하는 시간을 줄이고, 함께 실행하는 시간을 늘리고 싶다면 HANDA와 함께하세요.", "richText": {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "HANDA는 베를린에서 각자의 사업을 실제로 실행하고 성장시키는"}, {"type": "hardBreak"}, {"type": "text", "text": "창업자들의 커뮤니티입니다."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "함께하면 더 멀리 갈 수 있다는 믿음으로,"}, {"type": "hardBreak"}, {"type": "text", "text": "2025년 12월 작은 모임에서 시작했습니다."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "HANDA에서는 매달 목표를 세우고, 직접 실행하고,"}, {"type": "hardBreak"}, {"type": "text", "text": "같은 공간에서 서로의 과정을 솔직하게 리뷰합니다."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "단순히 경험을 나누는 데 그치지 않고,"}, {"type": "hardBreak"}, {"type": "text", "text": "다음 행동으로 이어지는 것이 HANDA가 추구하는 방식입니다."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "HANDA에서는 이렇게 함께 합니다.", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "[실행엔진]"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "매달 목표와 실행 결과, 진행 과정에서 막힌 점을 기록하고 공유합니다."}, {"type": "hardBreak"}, {"type": "text", "text": "각자의 계획이 실제 행동으로 이어지도록 돕습니다."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "[정기모임]"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "매달 둘째 주 일요일, 멤버들이 한자리에 모여"}, {"type": "hardBreak"}, {"type": "text", "text": "각자의 실행을 공유하고 서로의 고민과 병목을 함께 풀어갑니다."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "[비즈니스 위키]"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "실제 창업자들이 사업을 운영하며 얻은 경험과 실전 노하우를 공유합니다."}, {"type": "hardBreak"}, {"type": "text", "text": "법인 설립 절차와 비용부터 팝업스토어 기획 및 성사 과정까지,"}, {"type": "hardBreak"}, {"type": "text", "text": "검색만으로는 알기 어려운 생생한 정보를 서로 나눕니다."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "이런 분과 잘 맞습니다", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "· 베를린에서 사업을 운영하고 있거나 곧 런칭을 준비하는 분"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "· 혼자 고민하기보다 다른 창업자들과 함께 움직이고 싶은 분"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "· 좋은 아이디어를 실제 행동과 결과로 연결하고 싶은 분"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "함께 만든 변화", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "HANDA에서는 아이디어가 3개월 만에 실제 서비스로 발전하고,"}, {"type": "hardBreak"}, {"type": "text", "text": "첫 오프라인 이벤트가 열리고,"}, {"type": "hardBreak"}, {"type": "text", "text": "새로운 사업 기회와 협업이 연결되는 경험들이 만들어지고 있습니다."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "작은 실행이 모여 각자의 사업을 한 걸음씩 앞으로 나아가게 합니다."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "혼자 고민하는 시간을 줄이고, 함께 실행하는 시간을 늘리고 싶다면 HANDA와 함께하세요.", "marks": [{"type": "bold"}]}]}]}}}'::jsonb,'published',false,false,0),
('page','guide','{"isExample": false, "secondaryHeading": "", "secondaryBody": "", "ctaLabel": "HANDA 참여 신청하기", "ctaUrl": "https://forms.gle/SXXxb8321efoPFta8", "slug": "guide", "title": "운영 방식 및 참여 안내", "heading": "함께하는 방법을 안내해 드릴게요.", "body": "운영 방식과 참여 안내 내용을 준비하고 있습니다."}'::jsonb,'published',false,false,1),
('page','join','{"isExample": false, "secondaryHeading": "아직 참여를 고민 중이신가요?", "secondaryBody": "다음 기수 모집이 시작되면 안내받을 수 있어요.", "ctaLabel": "HANDA 참여 신청하기", "ctaUrl": "https://forms.gle/SXXxb8321efoPFta8", "slug": "join", "title": "HANDA에 참여하고 싶으신가요?", "heading": "참여 신청 안내", "body": "HANDA는 각자의 사업을 실행하며 얻은 경험과 고민을 나누고, 서로의 성장을 돕는 창업자 커뮤니티입니다."}'::jsonb,'published',false,false,2)
